package hikyubank;
import java.util.*;import java.math.BigDecimal;import java.time.*;import java.util.concurrent.*;
import com.fasterxml.jackson.databind.*;
import org.junit.jupiter.api.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;import org.springframework.test.context.*;import org.springframework.mock.web.MockHttpSession;import org.springframework.test.web.servlet.*;import org.springframework.test.web.servlet.request.MockMvcRequestBuilders;import org.springframework.http.*;import org.springframework.jdbc.core.JdbcTemplate;
import hikyubank.application.service.*;import hikyubank.application.dto.ExtensionDtos.*;import hikyubank.application.dto.SecurityDtos.*;import hikyubank.application.exception.BankException;import hikyubank.application.model.Account;
import static org.junit.jupiter.api.Assertions.*;
@SpringBootTest @AutoConfigureMockMvc
class ExtensionIntegrationTest {
 @Autowired SecurityService security;@Autowired TransferService transfers;@Autowired AccountService accounts;@Autowired SettingsService settings;@Autowired TransactionQueryService queries;@Autowired AlertService alerts;@Autowired NotificationService notifications;@Autowired AssistantService assistant;@Autowired JdbcTemplate jdbc;@Autowired MockMvc mvc;@Autowired ObjectMapper mapper;
 UUID user,source,target;String username;MockHttpSession session;static final String PASSWORD="TestingPassword2026!",PIN="0371";
 @DynamicPropertySource static void db(DynamicPropertyRegistry p){BankApiIntegrationTest.databaseProperties(p);}
 @BeforeEach void user(){username="test_"+UUID.randomUUID().toString().substring(0,8);user=security.register(new Registration(username,"Test","User",PASSWORD,PIN)).userId();source=accounts.list(user).stream().filter(a->a.type().equals("checking")).findFirst().orElseThrow().id();target=accounts.list(user).stream().filter(a->a.type().equals("savings")).findFirst().orElseThrow().id();session=login(username,PASSWORD,PIN);}
 TransferInput input(String amount,UUID key){return new TransferInput(source,target,new BigDecimal(amount),"Testing",key,PIN);}
 BigDecimal balance(UUID id){return accounts.get(user,id).balance();}
 MockHttpSession login(String name,String password,String pin){return login(name,password,pin,200,200);}
 MockHttpSession login(String name,String password,String pin,int loginExpected,int verifyExpected){try{var s=new MockHttpSession();var c=json(call(s,"POST","/auth/login",Map.of("username",name,"password",password),loginExpected));if(loginExpected!=200)return s;var code=json(call(s,"POST","/auth/code",Map.of("challengeId",c.path("challengeId").asText(),"method",verifyExpected==400?"email":"sms"),200));call(s,"POST","/auth/verify",Map.of("challengeId",c.path("challengeId").asText(),"method",verifyExpected==400?"email":"sms","code",code.path("demoCode").asText(),"pin",pin),verifyExpected);return s;}catch(Exception e){throw new RuntimeException(e);}}
 MvcResult call(MockHttpSession s,String method,String path,Object body,int expected)throws Exception{var q=MockMvcRequestBuilders.request(HttpMethod.valueOf(method),"/api/v1"+path).session(s).header("X-Hikyu-Request","web").contentType(MediaType.APPLICATION_JSON);if(body!=null)q.content(mapper.writeValueAsString(body));var r=mvc.perform(q).andReturn();assertEquals(expected,r.getResponse().getStatus(),r.getResponse().getContentAsString());return r;}
 JsonNode json(MvcResult r)throws Exception{return mapper.readTree(r.getResponse().getContentAsString());}
 @Test void transferCreatesTwoLegsAndPreservesTotal(){var r=transfers.transfer(user,input("100.25",UUID.randomUUID()));assertEquals(new BigDecimal("899.75"),balance(source));assertEquals(new BigDecimal("300.25"),balance(target));assertEquals(new BigDecimal("1200.00"),balance(source).add(balance(target)));assertEquals(2,jdbc.queryForObject("SELECT count(*) FROM hikyu.transactions WHERE transfer_id=?",Integer.class,r.id()));assertEquals(0,jdbc.queryForObject("SELECT sum(amount) FROM hikyu.transactions WHERE transfer_id=?",BigDecimal.class,r.id()).signum());}
 @Test void repeatedAndConflictingKeys(){var key=UUID.randomUUID();var r=transfers.transfer(user,input("10",key));assertEquals(r.id(),transfers.transfer(user,input("10.00",key)).id());assertEquals("IDEMPOTENCY_CONFLICT",assertThrows(BankException.class,()->transfers.transfer(user,input("11",key))).code());assertEquals(new BigDecimal("990.00"),balance(source));}
 @Test void rejectsInsufficientInvalidAndForeignAccounts(){assertEquals("INSUFFICIENT_FUNDS",assertThrows(BankException.class,()->transfers.transfer(user,input("1001",UUID.randomUUID()))).code());for(String a:List.of("0","-1","1.001"))assertThrows(BankException.class,()->transfers.transfer(user,input(a,UUID.randomUUID())));var other=security.register(new Registration("other_"+username,"Other","User",PASSWORD,"1928")).userId();var foreign=accounts.list(other).get(0).id();assertEquals(404,assertThrows(BankException.class,()->transfers.transfer(user,new TransferInput(source,foreign,BigDecimal.ONE,"",UUID.randomUUID(),PIN))).status());assertEquals(new BigDecimal("1000.00"),balance(source));}
 @Test void concurrentSameKeyDebitsOnlyOnce()throws Exception{var key=UUID.randomUUID();var pool=Executors.newFixedThreadPool(6);try{List<Callable<UUID>> tasks=new ArrayList<>();for(int i=0;i<12;i++)tasks.add(()->transfers.transfer(user,input("75",key)).id());var results=pool.invokeAll(tasks);Set<UUID> ids=new HashSet<>();for(var f:results)ids.add(f.get());assertEquals(1,ids.size());assertEquals(new BigDecimal("925.00"),balance(source));}finally{pool.shutdownNow();}}
 @Test void concurrentDistinctRequestsCannotOverdraw()throws Exception{var pool=Executors.newFixedThreadPool(2);try{var tasks=List.<Callable<Boolean>>of(()->attempt("700"),()->attempt("700"));int ok=0;for(var f:pool.invokeAll(tasks))if(f.get())ok++;assertEquals(1,ok);assertEquals(new BigDecimal("300.00"),balance(source));assertEquals(new BigDecimal("1200.00"),balance(source).add(balance(target)));}finally{pool.shutdownNow();}}
 boolean attempt(String a){try{transfers.transfer(user,input(a,UUID.randomUUID()));return true;}catch(BankException e){assertEquals("INSUFFICIENT_FUNDS",e.code());return false;}}
 @Test void transactionFailureRollsBackBalancesAndHistory(){jdbc.execute("CREATE OR REPLACE FUNCTION hikyu.test_reject_leg() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.name='Transfer in' THEN RAISE EXCEPTION 'test failure'; END IF; RETURN NEW; END $$");jdbc.execute("CREATE TRIGGER test_reject_leg BEFORE INSERT ON hikyu.transactions FOR EACH ROW EXECUTE FUNCTION hikyu.test_reject_leg()");try{assertThrows(Exception.class,()->transfers.transfer(user,input("10",UUID.randomUUID())));assertEquals(new BigDecimal("1000.00"),balance(source));assertEquals(0,transfers.list(user).size());assertEquals(0,notifications.list(user).size());}finally{jdbc.execute("DROP TRIGGER test_reject_leg ON hikyu.transactions");jdbc.execute("DROP FUNCTION hikyu.test_reject_leg()");}}
 @Test void automaticRemindersAreDeduplicatedAndRespectPreferences(){var rule=alerts.create(user,new hikyubank.application.dto.BankDtos.AlertRequest("low_balance",source,"Low funds","In-app",new BigDecimal("950"),null));var key=UUID.randomUUID();transfers.transfer(user,input("100",key));transfers.transfer(user,input("100",key));assertEquals(1,notifications.list(user).size());settings.preferences(user,new Preferences(false,false));transfers.transfer(user,input("1",UUID.randomUUID()));assertEquals(1,notifications.list(user).size());alerts.toggle(user,rule.id(),false);settings.preferences(user,new Preferences(true,true));transfers.transfer(user,input("1",UUID.randomUUID()));assertEquals(1,notifications.list(user).size());}
 @Test void largeTransferReminderAndFailedTransfer(){alerts.create(user,new hikyubank.application.dto.BankDtos.AlertRequest("large_transaction",source,"Large movement","In-app",new BigDecimal("100"),null));assertThrows(BankException.class,()->transfers.transfer(user,input("1001",UUID.randomUUID())));assertTrue(notifications.list(user).isEmpty());transfers.transfer(user,input("100",UUID.randomUUID()));assertEquals(1,notifications.list(user).size());}
 @Test void transactionSearchDetailsAndDateBoundaries(){transfers.transfer(user,input("42",UUID.randomUUID()));var p=queries.search(user,source,LocalDate.now(ZoneOffset.UTC),LocalDate.now(ZoneOffset.UTC),new BigDecimal("42"),new BigDecimal("42"),"transfer","Testing","Internal transfer","amount_desc",0,1);assertEquals(1,p.total());assertEquals(1,p.items().size());assertEquals("Testing",queries.detail(user,p.items().get(0).id()).note());assertTrue(queries.search(user,null,null,null,null,null,"expense","","","date_desc",0,10).items().isEmpty());assertThrows(BankException.class,()->queries.search(user,null,LocalDate.of(2026,2,2),LocalDate.of(2026,1,1),null,null,"all","","","date_desc",0,10));assertThrows(BankException.class,()->queries.search(user,null,null,null,null,null,"all","","","invalid",0,10));}
 @Test void paginationIsStableAndAssistantExcludesInternalTransfers(){for(int i=0;i<6;i++)transfers.transfer(user,input("1",UUID.randomUUID()));var first=queries.search(user,null,null,null,null,null,"transfer","","","date_desc",0,5);var second=queries.search(user,null,null,null,null,null,"transfer","","","date_desc",1,5);assertEquals(12,first.total());var ids=new HashSet<UUID>();first.items().forEach(t->ids.add(t.id()));second.items().forEach(t->assertTrue(ids.add(t.id())));assertTrue(assistant.ask(user,"savings").reply().contains("Recorded income is $0.00 and spending is $0.00"));}
 @Test void settingsPersistAndProtectedFieldsAreRejected()throws Exception{call(session,"PATCH","/accounts/"+source+"/nickname",Map.of("name","My checking"),200);assertEquals("My checking",accounts.get(user,source).name());call(session,"PUT","/settings/preferences",Map.of("lowBalance",false,"largeTransaction",true),200);assertFalse(settings.preferences(user).lowBalance());call(session,"PATCH","/accounts/"+source+"/nickname",Map.of("name","Bad","balance",123),400);call(session,"PATCH","/accounts/"+UUID.randomUUID()+"/nickname",Map.of("name","Bad"),404);}
 @Test void passwordChangeInvalidatesBothOldSessions()throws Exception{var other=login(username,PASSWORD,PIN);call(session,"POST","/settings/password",Map.of("currentPassword","incorrect","newPassword","ChangedPassword2026!"),400);call(session,"POST","/settings/password",Map.of("currentPassword",PASSWORD,"newPassword","ChangedPassword2026!"),204);call(other,"GET","/accounts",null,401);login(username,"ChangedPassword2026!",PIN);login(username,PASSWORD,PIN,401,200);}
 @Test void userChosenPinIsHashedAndRequiredForEmailAndTransfer()throws Exception{String hash=jdbc.queryForObject("SELECT pin_hash FROM hikyu.users WHERE id=?",String.class,user);assertNotEquals(PIN,hash);assertTrue(hash.startsWith("$2"));login(username,PASSWORD,"9999",200,400);assertThrows(BankException.class,()->transfers.transfer(user,new TransferInput(source,target,BigDecimal.ONE,"",UUID.randomUUID(),"9999")));call(session,"POST","/settings/security/pin",Map.of("password",PASSWORD,"newPin","8072"),200);login(username,PASSWORD,"8072");login(username,PASSWORD,PIN,200,400);}
 @Test void registrationRejectsDuplicateAndMalformedPin()throws Exception{call(new MockHttpSession(),"POST","/auth/register",Map.of("username",username,"firstName","A","lastName","B","password",PASSWORD,"pin","1234"),409);call(new MockHttpSession(),"POST","/auth/register",Map.of("username","valid_name","firstName","A","lastName","B","password",PASSWORD,"pin","123"),400);}
 @Test void fixedDemoPinsAreDistinctAndNeverReinitialized(){var pins=Map.of("chengyang.lee","1037","gospelhope.david","5842","mingyu.fan","9061");var encoder=new org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder();for(var e:pins.entrySet()){String hash=jdbc.queryForObject("SELECT pin_hash FROM hikyu.users WHERE username=?",String.class,e.getKey());assertTrue(encoder.matches(e.getValue(),hash));}security.rotatePin(user,PASSWORD,"8940");jdbc.update("UPDATE hikyu.users SET pin_initialized=FALSE WHERE id=?",user);security.initializePins();assertTrue(encoder.matches("8940",jdbc.queryForObject("SELECT pin_hash FROM hikyu.users WHERE id=?",String.class,user)));}
 @Test void staleLoginChallengeCannotSurvivePasswordChange()throws Exception{var pending=new MockHttpSession();var challenge=json(call(pending,"POST","/auth/login",Map.of("username",username,"password",PASSWORD),200));var code=json(call(pending,"POST","/auth/code",Map.of("challengeId",challenge.path("challengeId").asText(),"method","sms"),200));call(session,"POST","/settings/password",Map.of("currentPassword",PASSWORD,"newPassword","ChangedPassword2026!"),204);call(pending,"POST","/auth/verify",Map.of("challengeId",challenge.path("challengeId").asText(),"method","sms","code",code.path("demoCode").asText(),"pin",PIN),400);}
 @Test void revokeAllSessionsAndAnonymousProtection()throws Exception{var second=login(username,PASSWORD,PIN);call(session,"POST","/settings/security/logout-all",Map.of("password",PASSWORD),204);call(second,"GET","/settings/security",null,401);call(new MockHttpSession(),"GET","/transfers",null,401);}
 @Test void invalidRecipientReturnsEnglishWithoutValidatorRegexUnderChineseLocale()throws Exception{var r=mvc.perform(MockMvcRequestBuilders.post("/api/v1/payments/recipient").session(session).locale(Locale.SIMPLIFIED_CHINESE).header("X-Hikyu-Request","web").contentType(MediaType.APPLICATION_JSON).content(mapper.writeValueAsString(Map.of("username","Chengyang Lee")))).andReturn();assertEquals(400,r.getResponse().getStatus());String message=json(r).path("message").asText();assertTrue(message.contains("lowercase username"));assertFalse(message.codePoints().anyMatch(c -> c >= 0x4e00 && c <= 0x9fff));assertFalse(message.contains("{2,79}"));}
 @Test void securityMetadataRequiresPinForBothLoginMethods()throws Exception{var result=json(call(session,"GET","/settings/security",null,200));assertTrue(result.path("smsRequiresPin").asBoolean());assertTrue(result.path("emailRequiresPin").asBoolean());}

}
